effect.shader:
float h(vec2 p){return fract(sin(dot(p,vec2(12.9898,78.233)))*43758.5453);}void main(){vec2 uv=acScreenNorm;vec4 src=texture2DCv(inputImg.texture,uv);float t=acTime*scanSpeed;vec2 p=(uv-.5)*gridScale;float grid=pow(max(cos(p.x*3.14159265)*cos(p.y*3.14159265),0.0),8.0);float scan=pow(.5+.5*sin((uv.y+t)*gridScale*3.14159265),10.0);float fringe=.5+.5*sin((uv.x+uv.y*depth)*gridScale*interference+t*6.0);float noise=1.0-flicker*h(vec2(floor(acTime*18.0),floor(uv.y*90.0)));float silhouette=clamp(src.a+dot(src.rgb,vec3(.2126,.7152,.0722)),0.0,1.0);float energy=(grid*.35+scan+fringe*.18)*noise*silhouette*intensity;vec3 light=holoColor.rgb*energy*(.7+.3*cos(vec3(0,2.1,4.2)+uv.x*12.0));vec3 outRgb=src.rgb+light;gl_FragColor=vec4(mix(src.rgb,outRgb,mixAmount),src.a+clamp(energy,0.0,1.0)*mixAmount*(1.0-src.a));
gl_FragColor *= texture2DCv(inputImg.texture, acScreenNorm).a;
}
